import subprocess
import sys
import types

class Transport:
    def __init__(self, error=None):
        self.request = None
        self.error = error
    def put(self, path, body):
        self.request = (path, body)
        if self.error:
            raise self.error
        return {'ok': True}

for revision in ('HEAD', ''):
    payload = types.ModuleType('payload')
    exec(compile(subprocess.check_output(['git', 'show', revision + ':payload.py']), 'payload.py', 'exec'), payload.__dict__)
    sys.modules['payload'] = payload
    client = types.ModuleType('review_client')
    exec(compile(subprocess.check_output(['git', 'show', revision + ':client.py']), 'client.py', 'exec'), client.__dict__)
    print('BASE' if revision else 'STAGED')
    for name in ('Ada', '  Ada  ', 'Ada Lovelace', '', '   ', '\tAda\n', '  Åsa 李  ', None):
        transport = Transport()
        try:
            result = client.save(transport, name)
            print(repr(name), '->', transport.request, result)
        except Exception as error:
            print(repr(name), '->', type(error).__name__, 'request:', transport.request)
    error = OSError('transport failed')
    try:
        client.save(Transport(error), 'Ada')
    except OSError as caught:
        print('Transport failure propagated unchanged:', caught is error)
